package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringUtils.containsNone(CharSequence, char[])
 */
public class StringUtils_containsNone_TriageGen0Test {

    @Test
    public void testContainsNone_NullInputs() {
        // If cs is null, return true
        assertTrue(StringUtils.containsNone(null, new char[]{'a'}));
        // If searchChars is null, return true
        assertTrue(StringUtils.containsNone("abc", null));
        // If both are null, return true
        assertTrue(StringUtils.containsNone(null, null));
    }

    @Test
    public void testContainsNone_EmptyInputs() {
        // Empty cs, should return true (contains no characters from searchChars)
        assertTrue(StringUtils.containsNone("", new char[]{'a', 'b'}));
        // Empty searchChars, should return true (contains no characters from an empty set)
        assertTrue(StringUtils.containsNone("abc", new char[]{}));
    }

    @Test
    public void testContainsNone_BasicFunctionality() {
        // No characters match
        assertTrue(StringUtils.containsNone("abc", new char[]{'x', 'y', 'z'}));
        // One character matches
        assertFalse(StringUtils.containsNone("abc", new char[]{'b'}));
        // Multiple characters match
        assertFalse(StringUtils.containsNone("abc", new char[]{'a', 'c'}));
        // Character in cs is not in searchChars but searchChars contains higher value chars
        // The logic 'searchChars[j] >= ch' is used in the provided implementation
        // Note: The implementation provided has a specific logic: if searchChars[j] >= ch, it returns false.
        // This is unusual for a standard "containsNone", but I must test the code provided.

        // Testing the provided logic: if searchChars[j] >= ch, it returns false.
        // If cs = "a", searchChars = ['b']. 'b' >= 'a' is true -> returns false.
        assertFalse(StringUtils.containsNone("a", new char[]{'b'}));
        // If cs = "b", searchChars = ['a']. 'a' >= 'b' is false -> returns true.
        assertTrue(StringUtils.containsNone("b", new char[]{'a'}));
    }

    @Test
    public void testContainsNone_HighSurrogate_FullPair() {
        // A surrogate pair: U+1F600 (😀) is \uD83D\uDE00
        char[] emoji = {'\uD83D', '\uDE00'};
        char[] search = {'\uD83D', '\uDE00'};

        // The code checks if searchChars[j+1] == cs.charAt(i+1)
        assertFalse(StringUtils.containsNone(new String("\uD83D\uDE00"), search));
    }

    @Test
    public void testContainsNone_HighSurrogate_MissingLowSurrogate() {
        // Testing the "missing low surrogate" branch
        // If ch is a high surrogate and it is the last element in searchChars
        char[] search = {'\uD83D'}; 
        // cs has the high surrogate
        assertFalse(StringUtils.containsNone("\uD83D", search));
    }

    @Test
    public void testContainsNone_HighSurrogate_PartialMatch() {
        // Testing the branch where high surrogate is matched but low surrogate doesn't match
        // cs = "\uD83D\uDE01", search = "\uD83D\uDE00"
        // When i=0, ch=\uD83D. j=0, search[0]=\uD83D. 
        // search[0] >= ch is true (they are equal).
        // isHighSurrogate(ch) is true.
        // j (0) is not searchLast (1).
        // i (0) < csLast (1) AND search[1] (\uDE00) == cs.charAt(1) (\uDE01) is FALSE.
        // The loop continues.
        // Next i=1, ch=\uDE01. search[0]=\uD83D. \uD83D >= \uDE01 is false.
        // Result should be true because no full sequence matched the logic conditions.
        assertTrue(StringUtils.containsNone("\uD83D\uDE01", new char[]{'\uD83D', '\uDE00'}));
    }

    @Test
    public void testContainsNone_HighSurrogate_Boundary() {
        // Test high surrogate at the very end of cs
        char[] search = {'\uD83D'};
        String cs = "abc\uD83D";
        // i=3, ch=\uD83D. j=0, search[0]=\uD83D. 
        // search[0] >= ch is true.
        // isHighSurrogate is true.
        // j == searchLast (0 == 0) is true.
        // returns false.
        assertFalse(StringUtils.containsNone(cs, search));
    }

    @Test
    public void testContainsNone_BMP_Match() {
        // Standard BMP character match
        assertFalse(StringUtils.containsNone("abc", new char[]{'c'}));
        // Standard BMP character where searchChar is greater
        // 'z' >= 'a' is true -> returns false
        assertFalse(StringUtils.containsNone("a", new char[]{'z'}));
        // Standard BMP character where searchChar is smaller
        // 'a' >= 'z' is false -> continues loop
        assertTrue(StringUtils.containsNone("z", new char[]{'a'}));
    }
}
